window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[276]={"id":"276","numero":276,"titre":"Hépatomégalie - masse abdominale","objectifs":[{"id":"276-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition d’une masse abdominale","contenu":"<p>Une <span class=\"kw-clinique\">masse abdominale</span> se définit comme une <span class=\"kw-def\">augmentation de volume d’un organe ou d’une région de l’abdomen</span>. Sa découverte impose une <span class=\"kw-clinique\">analyse topographique</span> rigoureuse : la <span class=\"kw-clinique\">masse</span> est rapportée à l’un des quadrants de la paroi abdominale, ce qui oriente d’emblée vers <span class=\"kw-clinique\">les</span> organes sous-jacents et les étiologies possibles.</p>\n      <p>L’examen commence par éliminer <span class=\"kw-clinique\">les</span> <span class=\"kw-clinique\">éventrations</span>, les <span class=\"kw-clinique\">hernies</span> et les <span class=\"kw-clinique\">distensions abdominales</span>, puis précise les caractères de la <span class=\"kw-clinique\">masse</span> : localisation sur un quadrant, taille, forme, contours, consistance, caractère mobile ou fixe, caractère indolore ou douloureux, percussion et auscultation.</p>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Masses abdominales selon la localisation</h4>\n      <table >\n        <thead><tr><th>Région</th><th>Causes principales</th></tr></thead>\n        <tbody>\n          <tr><td>Hypochondre droit</td><td><span class=\"kw-clinique\">Hépatomégalie</span> ; <span class=\"kw-clinique\">lésion</span> de l’angle colique droit, du rein droit ou de la surrénale droite ; <strong>grosse <span class=\"kw-clinique\">vésicule</span> biliaire</strong> (mobile avec la respiration) : <span class=\"kw-etio\">tumeur maligne de la tête du pancréas</span>, hydrocholécyste, <span class=\"kw-clinique\">cholécystite</span> aiguë, <span class=\"kw-etio\">cancer de la vésicule</span></td></tr>\n          <tr><td>Ép<span class=\"kw-chiffre\">iga</span>stre</td><td>Hypertrophie du <span class=\"kw-clinique\">lobe gauche du foie</span> ; <span class=\"kw-etio\">tumeur gastrique</span> ; tumeur de la queue du pancréas ; lésions du côlon transverse</td></tr>\n          <tr><td>Hypochondre gauche</td><td><strong><span class=\"kw-clinique\">Splénomégalie</span> homogène :</strong> <span class=\"kw-clinique\">hypertension</span> portale, infection, hémolyse, hémopathie ; <br><strong>Splénomégalie hétérogène :</strong> <span class=\"kw-clinique\">abcès</span>, kyste hydatique, tumeur ; <br><strong>Autres origines :</strong> tumeur de la queue du pancréas, grosse tubérosité gastrique, angle colique gauche, rein gauche</td></tr>\n          <tr><td>Flanc droit</td><td><span class=\"kw-clinique\">Lésion</span> rénale (<span class=\"kw-etio\">tumeur maligne</span>, hydronéphrose) ; lésion surrénalienne (tumeur bénigne ou maligne) ; <span class=\"kw-etio\">tumeur rétropéritonéale primitive</span> (sarcome) ; lésions du psoas (hématome, <span class=\"kw-clinique\">abcès</span>, tumeur) ; cancer du côlon (exceptionnellement palpé)</td></tr>\n          <tr><td>Flanc gauche</td><td><span class=\"kw-clinique\">Lésion</span> rénale (<span class=\"kw-etio\">tumeur maligne</span>, hydronéphrose) ; lésion surrénalienne (tumeur bénigne ou maligne) ; <span class=\"kw-etio\">tumeur rétropéritonéale primitive</span> (sarcome) ; lésions du psoas (hématome, <span class=\"kw-clinique\">abcès</span>, tumeur) ; cancer du côlon (exceptionnellement palpé)</td></tr>\n          <tr><td>Région ombilicale</td><td><span class=\"kw-etio\">Anévrisme de l’aorte abdominale</span> ; cancer du côlon transverse ; tumeurs du grêle ; tumeur mésentérique</td></tr>\n          <tr><td>Fosse iliaque droite</td><td>Kyste de l’ovaire ; <span class=\"kw-etio\">tumeur du cæcum</span> ; <span class=\"kw-clinique\">appendicite</span> dans sa forme abcédée ; <span class=\"kw-etio\">maladie de Crohn</span> compliquée d’un <span class=\"kw-clinique\">abcès</span></td></tr>\n          <tr><td>Hypogastre</td><td><strong>À éliminer en premier :</strong> fécalome, <span class=\"kw-ci\">grossesse</span>, globe vésical ; <br><strong>Causes utéro-ovariennes :</strong> fibrome utérin, <span class=\"kw-etio\">cancer de l’endomètre</span>, <span class=\"kw-etio\">cancer de l’ovaire</span></td></tr>\n          <tr><td>Fosse iliaque gauche</td><td>Kyste de l’ovaire ; <span class=\"kw-etio\">tumeur sigmoïdienne</span> ; s<span class=\"kw-chiffre\">igm</span>oïdite avec <span class=\"kw-clinique\">abcès</span> péri-sigmoïdien</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">📌 <strong>Masses ubiquitaires</strong> — observables dans diverses régions : <span class=\"kw-etio\">carcinose péritonéale</span>, <span class=\"kw-clinique\">adénopathies</span>, hernies et éventrations, hématome de paroi, lipome.</div>","frequence":0},{"id":"276-2","rang":"B","rubrique":"Etiologie","titre":"Connaître les principales causes d’hépatomégalie et de masse abdominale","contenu":"<p>L’<span class=\"kw-clinique\">hépatomégalie</span> et <span class=\"kw-clinique\">les</span> masses abdominales relèvent d’étiologies nombreuses, présentées ci-dessous en deux tableaux : les causes d’<span class=\"kw-clinique\">hépatomégalie</span> classées par mécanisme, puis les masses abdominales palpables selon leur siège.</p>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Principales causes d’<span class=\"kw-clinique\">hépatomégalie</span></h4>\n      <table >\n        <thead><tr><th>Catégorie / mécanisme</th><th>Pathologies</th></tr></thead>\n        <tbody>\n          <tr><td>Maladies hépatiques primitives, aiguës ou chroniques</td><td><span class=\"kw-etio\">Stéatose / stéato-hépatite</span> liée à l’<span class=\"kw-etio\">alcool</span> ou métabolique ; <span class=\"kw-etio\">cirrhose</span> (l’<span class=\"kw-clinique\">hépatomégalie</span> y est inconstante) ; <span class=\"kw-etio\">hépatites</span> aiguës ou chroniques</td></tr>\n          <tr><td>Congestion par obstacle au retour veineux hépatique</td><td><span class=\"kw-etio\">Insuffisance cardiaque droite</span>, péricardite <span class=\"kw-clinique\">constrictive</span> ; <span class=\"kw-etio\">syndrome de Budd-Chiari</span> (exceptionnel)</td></tr>\n          <tr><td>Tumeurs hépatiques</td><td><strong>Malignes :</strong> primitives — <span class=\"kw-etio\">carcinome hépatocellulaire</span>, <span class=\"kw-etio\">cholangiocarcinome</span> ; secondaires — <span class=\"kw-etio\">métastases</span> ; hémopathie maligne (très rare) ; <br><strong>Bénignes :</strong> polykystose hépatique ou hépatorénale ; autres tumeurs bénignes (<span class=\"kw-clinique\">hépatomégalie</span> exceptionnelle)</td></tr>\n          <tr><td>Atteintes infectieuses</td><td><span class=\"kw-etio\">Abcès hépatique</span> amibien ou <span class=\"kw-etio\">bactérien</span> ; <span class=\"kw-etio\">lésion parasitaire</span> (hydatidose)</td></tr>\n        </tbody>\n      </table>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Masses abdominales palpables selon le siège</h4>\n      <table >\n        <thead><tr><th>Siège</th><th>Organe</th><th>Cause</th></tr></thead>\n        <tbody>\n          <tr><td>Ép<span class=\"kw-chiffre\">iga</span>stre</td><td>Estomac, pancréas, foie</td><td><span class=\"kw-etio\">Tumeur gastrique</span> ; tumeur ou pseudo-kyste pancréatique (rarement palpables) ; <span class=\"kw-clinique\">hépatomégalie</span> aux dépens du foie gauche</td></tr>\n          <tr><td>Hypochondre droit</td><td>Foie, <span class=\"kw-clinique\">vésicule</span> biliaire</td><td><span class=\"kw-clinique\">Hépatomégalie</span> ; obstacle biliaire du bas cholédoque (ex. cancer de la tête du pancréas) ; <span class=\"kw-etio\">tumeur maligne de la vésicule</span></td></tr>\n          <tr><td>Hypochondre et flanc gauches</td><td>Rate</td><td><span class=\"kw-clinique\">Splénomégalie</span></td></tr>\n          <tr><td>Fosse iliaque droite</td><td>Cæcum, ovaire droit</td><td><span class=\"kw-etio\">Cancer du côlon droit</span> ; <span class=\"kw-etio\">maladie de Crohn</span> (iléite, <span class=\"kw-clinique\">abcès</span>) ; <span class=\"kw-clinique\">abcès</span> appendiculaire (rare) ; kyste ovarien ; <span class=\"kw-etio\">tumeur ovarienne</span></td></tr>\n          <tr><td>Fosse iliaque gauche</td><td>S<span class=\"kw-chiffre\">igm</span>oïde, ovaire gauche</td><td><span class=\"kw-clinique\">Constipation</span> ; <span class=\"kw-etio\">tumeur du sigmoïde</span> ; s<span class=\"kw-chiffre\">igm</span>oïdite ; kyste ovarien ; <span class=\"kw-etio\">tumeur ovarienne</span></td></tr>\n          <tr><td>Région ombilicale</td><td>Aorte, côlon transverse, grêle</td><td><span class=\"kw-etio\">Anévrysme de l’aorte abdominale</span> ; <span class=\"kw-etio\">cancer colique</span> ; tumeur du grêle (rare)</td></tr>\n          <tr><td>Hypogastre</td><td>Utérus, vessie</td><td><span class=\"kw-ci\">Grossesse</span> ; fibromyome utérin ; <span class=\"kw-etio\">cancer de l’endomètre</span> ; globe vésical ; <span class=\"kw-etio\">tumeur vésicale</span></td></tr>\n          <tr><td>Ubiquitaire</td><td>Péritoine, ganglions, paroi</td><td><span class=\"kw-etio\">Carcinose péritonéale</span> ; <span class=\"kw-clinique\">adénopathies</span> (lymphome, métastases) ; hernies et éventrations</td></tr>\n        </tbody>\n      </table>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\"><span class=\"kw-clinique\">Hépatomégalie</span> selon le caractère focal ou non de l’imagerie</h4>\n      <table >\n        <thead><tr><th>Profil</th><th>Étiologie</th><th>Repères clinico-bio-radiologiques</th></tr></thead>\n        <tbody>\n          <tr><td rowspan=\"6\"><strong>Sans <span class=\"kw-clinique\">lésion</span> focale</strong></td><td><span class=\"kw-etio\">Stéatose</span></td><td><span class=\"kw-etio\">Alcool</span>, <span class=\"kw-etio\">syndrome métabolique</span> ; <span class=\"kw-radio\">parenchyme hépatique hyperéchogène</span></td></tr>\n          <tr><td><span class=\"kw-etio\">Cirrhose</span></td><td>FdR de cirrhose, signes d’<span class=\"kw-clinique\">IHC</span> et/ou d’<span class=\"kw-clinique\">HTP</span> ; clinique : <span class=\"kw-clinique\">foie dur à la palpation</span>, <span class=\"kw-clinique\">HMG à bord tranchant</span> ; écho : <span class=\"kw-radio\">contours bosselés</span>, <span class=\"kw-clinique\">hépatomégalie</span> diffuse ou sectorielle, parfois absente</td></tr>\n          <tr><td><span class=\"kw-etio\">Insuffisance cardiaque</span></td><td>FdR, cardiopathie connue, signes d’<span class=\"kw-clinique\">insuffisance cardiaque</span> ; <span class=\"kw-radio\">veines hépatiques dilatées</span> à l’imagerie</td></tr>\n          <tr><td><span class=\"kw-etio\">Cholestase chronique</span></td><td><span class=\"kw-clinique\">Prurit</span>, <span class=\"kw-clinique\">ictère</span> ; <span class=\"kw-radio\">dilatation des voies biliaires</span></td></tr>\n          <tr><td><span class=\"kw-etio\">Infiltration tumorale</span></td><td><span class=\"kw-clinique\">Altération de l’état général</span> ; <span class=\"kw-etio\">hémopathies</span> (lymphome), <span class=\"kw-etio\">cancer du sein</span> (rare)</td></tr>\n          <tr><td><span class=\"kw-etio\">Syndrome de Budd-Chiari</span></td><td><span class=\"kw-clinique\">Ascite</span> ; <span class=\"kw-radio\">veines hépatiques non visualisées</span> à l’imagerie</td></tr>\n          <tr><td rowspan=\"3\"><strong>Avec <span class=\"kw-clinique\">lésion</span> focale</strong></td><td><span class=\"kw-etio\">Tumeur hépatique</span></td><td><strong>Bénigne :</strong> polykystose hépatique ou hépato-rénale (<span class=\"kw-clinique\">les</span> autres tumeurs bénignes causent rarement une HMG) ; <strong>Maligne :</strong> <span class=\"kw-etio\">CHC</span>, <span class=\"kw-etio\">cholangiocarcinome</span> ; <strong>Secondaire :</strong> contexte de cancer connu, signes en lien avec le primitif</td></tr>\n          <tr><td><span class=\"kw-etio\">Abcès hépatique</span></td><td><span class=\"kw-clinique\">Syndrome septique</span> → <span class=\"kw-clinique\">abcès</span> amibien ou <span class=\"kw-etio\">bactérien</span></td></tr>\n          <tr><td><span class=\"kw-etio\">Parasitoses</span></td><td>Séjour en <span class=\"kw-clinique\">zone d’endémie</span> (<span class=\"kw-etio\">hydatidose</span>)</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 279 — <span class=\"kw-etio\">Cirrhose</span> · 304 — Tumeur du foie · 234 — <span class=\"kw-etio\">Insuffisance cardiaque</span> · 219 — Pathologie du fer · 275 — <span class=\"kw-clinique\">Splénomégalie</span> · 308 — Tumeur pancréas · 303 — Tumeur estomac · 301 — Tumeur colon - rectum · 306 — Tumeur ovaire · 225 — Artériopathie oblitérante - anévrysme</em></p>","frequence":1},{"id":"276-3","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître la démarche diagnostique devant une hépatomégalie et une masse abdominale","contenu":"<p>La démarche est <span class=\"kw-clinique\">clinique d’abord</span> : la <span class=\"kw-clinique\">palpation</span> caractérise la <span class=\"kw-clinique\">masse</span> — <span class=\"kw-clinique\">siège</span>, <span class=\"kw-clinique\">taille</span>, <span class=\"kw-clinique\">consistance</span>, <span class=\"kw-clinique\">mobilité</span> — puis l’<span class=\"kw-imagerie\">échographie abdominale</span>, réalisée dans le prolongement de l’examen clinique, <span class=\"kw-imagerie\">confirme l’hépatomégalie</span>, écarte <span class=\"kw-clinique\">les</span> autres <span class=\"kw-clinique\">masses abdominales</span> et oriente l’étiologie.</p>\n      <p>Devant une <span class=\"kw-clinique\">hépatomégalie</span>, l’<span class=\"kw-imagerie\">échographie</span> distingue <strong>trois profils</strong> qui commandent la suite des explorations.</p>\n      <table >\n        <thead><tr><th>Profil échographique</th><th>Orientation étiologique</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\">Hépatomégalie</span> <span class=\"kw-radio\">diffuse et homogène</span></td><td><span class=\"kw-etio\">Cirrhose</span>, <span class=\"kw-etio\">stéatose / stéato-hépatite</span>, <span class=\"kw-etio\">foie cardiaque</span>, <span class=\"kw-etio\">hépatite aiguë ou chronique</span>, <span class=\"kw-etio\">hémochromatose</span>, <span class=\"kw-etio\">cholestase chronique</span></td></tr>\n          <tr><td><span class=\"kw-clinique\">Hépatomégalie</span> <span class=\"kw-radio\">sectorielle mais homogène</span></td><td><span class=\"kw-etio\">Cirrhose</span> (diagnostic le plus fréquent) ; plus rarement, <span class=\"kw-etio\">hypertrophie compensatrice</span> répondant à l’atrophie d’un autre secteur (obstruction des voies biliaires, des veines hépatiques ou portes du secteur atrophié)</td></tr>\n          <tr><td><span class=\"kw-clinique\">Hépatomégalie</span> <span class=\"kw-radio\">hétérogène</span></td><td>Doit faire chercher une <span class=\"kw-etio\">tumeur du foie</span>, traduite par des <span class=\"kw-radio\">nodules</span> ou des <span class=\"kw-radio\">plages de parenchyme anormal</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">⚠️ Toute <span class=\"kw-alerte\">hépatomégalie hétérogène doit faire chercher une tumeur du foie</span> jusqu’à preuve du contraire.</div>\n      <p>Lorsque la confrontation <span class=\"kw-clinique\">clinique</span>, <span class=\"kw-bio\">biologique</span> et <span class=\"kw-imagerie\">radiologique</span> ne permet pas d’établir la cause, la <span class=\"kw-clinique\">ponction-biopsie hépatique</span> est indiquée.</p>","frequence":0},{"id":"276-4","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les éléments de l’interrogatoire et de l’examen physique aidant au diagnostic d’hépatomégalie et de masse abdominale","contenu":"<p>Devant une <span class=\"kw-clinique\">hépatomégalie</span> ou une <span class=\"kw-clinique\">masse</span> abdominale, l’<span class=\"kw-clinique\">interrogatoire</span> et l’<span class=\"kw-clinique\">examen physique</span> orientent fortement le diagnostic et conditionnent le choix des examens complémentaires.</p>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Interrogatoire</h4>\n      <ul>\n        <li><strong>Circonstances de découverte :</strong> fortuite, <span class=\"kw-def\">dépistage</span>, <span class=\"kw-clinique\">douleur</span>, <span class=\"kw-clinique\">ictère</span></li>\n        <li><strong>Date d’apparition et <span class=\"kw-clinique\">évolution</span></strong> de la <span class=\"kw-clinique\">masse</span></li>\n        <li><strong>Contexte :</strong> voyage en zone d’endémie</li>\n        <li><strong><span class=\"kw-def\">Facteurs de risque</span> de <span class=\"kw-etio\">cirrhose</span> :</strong> consommation d’<span class=\"kw-etio\">alcool</span>, <span class=\"kw-etio\">syndrome métabolique</span>, facteurs de risque d’<span class=\"kw-etio\">hépatite virale</span></li>\n        <li><strong>Antécédents :</strong> médicaux, chirurgicaux et gynécologiques ; <span class=\"kw-etio\">antécédents familiaux</span> de cancers</li>\n        <li><strong>Traitements :</strong> <span class=\"kw-clinique\">les</span> <span class=\"kw-ttt\">anticoagulants</span> favorisent la survenue d’un <span class=\"kw-clinique\">hématome de la paroi abdominale</span> (faux aspect de <span class=\"kw-clinique\">masse</span> abdominale)</li>\n        <li><strong>Signes associés :</strong> <span class=\"kw-clinique\">fièvre</span>, <span class=\"kw-clinique\">sueurs</span>, <span class=\"kw-clinique\">amaigrissement</span>, troubles du transit, signes urinaires ou gynécologiques</li>\n        <li><strong>Date des dernières règles</strong> chez la femme non ménopausée</li>\n        <li><strong><span class=\"kw-alerte\">Femme en âge de procréer :</span></strong> penser à la <span class=\"kw-etio\">grossesse extra-utérine</span></li>\n      </ul>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Examen physique</h4>\n      <ul>\n        <li>Caractériser la <span class=\"kw-clinique\">masse</span> : localisation, taille, consistance, douleur spontanée ou provoquée, fixation aux plans profonds, caractère pulsatile</li>\n        <li><span class=\"kw-clinique\">Mobilité avec la respiration</span> : une <span class=\"kw-clinique\">masse</span> de l’hypochondre droit ou de l’ép<span class=\"kw-chiffre\">iga</span>stre mobile à la respiration est rattachée à une origine hépatique</li>\n        <li>Recherche d’un <span class=\"kw-clinique\">syndrome septique</span> : <span class=\"kw-clinique\">fièvre</span>, <span class=\"kw-clinique\">frissons</span></li>\n        <li>Recherche d’un <span class=\"kw-clinique\">syndrome de cholestase</span> : <span class=\"kw-clinique\">ictère</span>, <span class=\"kw-clinique\">prurit</span>, selles décolorées, urines foncées</li>\n        <li>Recherche de signes d’<span class=\"kw-clinique\">insuffisance hépatocellulaire</span> et d’<span class=\"kw-clinique\">hypertension portale</span></li>\n        <li>Recherche de <span class=\"kw-etio\">métastases</span> : palpation du foie et des aires ganglionnaires (<span class=\"kw-clinique\">adénopathie de Troisier</span>), <span class=\"kw-clinique\">nodules de carcinose</span>, touchers pelviens</li>\n        <li>Recherche de signes d’<span class=\"kw-clinique\">insuffisance cardiaque droite</span> — <span class=\"kw-clinique\">reflux hépatojugulaire</span>, expansion systolique du foie — et d’une <span class=\"kw-clinique\">ascite</span></li>\n      </ul>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Caractères sémiologiques de la <span class=\"kw-clinique\">masse</span> à préciser</h4>\n      <table >\n        <thead><tr><th>Caractère</th><th>Modalités</th></tr></thead>\n        <tbody>\n          <tr><td>Localisation</td><td>Rapportée à l’un des quadrants de l’abdomen</td></tr>\n          <tr><td>Taille et forme</td><td>Taille de la <span class=\"kw-clinique\">masse</span> ; forme arrondie ou polylobée</td></tr>\n          <tr><td>Contours</td><td>Réguliers ou irréguliers, nets ou mal définis</td></tr>\n          <tr><td>Consistance</td><td>Rénitente, ferme ou dure ; homogène ou non</td></tr>\n          <tr><td>Mobilité</td><td>Mobile ou fixe ; mobilité avec la respiration en faveur d’une origine hépatique</td></tr>\n          <tr><td>Sensibilité</td><td>Indolore ou douloureuse, spontanément ou à la palpation</td></tr>\n          <tr><td>Percussion</td><td>Sonorité ou matité</td></tr>\n          <tr><td>Auscultation</td><td>Recherche d’un souffle</td></tr>\n        </tbody>\n      </table>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Signes orientant vers une hépatopathie</h4>\n      <table >\n        <thead><tr><th>Syndrome</th><th>Signes cliniques</th></tr></thead>\n        <tbody>\n          <tr><td>Insuffisance hépatocellulaire</td><td><span class=\"kw-clinique\">Ictère</span> conjonctival ou cutané ; <span class=\"kw-clinique\">fœtor hepaticus</span> ; <span class=\"kw-clinique\">angiomes stellaires</span> ; <span class=\"kw-clinique\">érythrose palmaire</span> ; <span class=\"kw-clinique\">ongles blancs</span> ; <span class=\"kw-alerte\">encéphalopathie hépatique</span> (<span class=\"kw-clinique\">astérixis</span>, inversion du cycle nycthéméral) ; <span class=\"kw-clinique\">hypogonadisme</span></td></tr>\n          <tr><td><span class=\"kw-clinique\">Hypertension</span> portale</td><td><span class=\"kw-clinique\">Ascite</span> ; <span class=\"kw-clinique\">circulation veineuse collatérale</span> abdominale ; <span class=\"kw-clinique\">splénomégalie</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">⚠️ La palpation d’un <span class=\"kw-clinique\">foie dur à bord inférieur tranchant</span> est très évocatrice d’une <span class=\"kw-etio\">cirrhose</span> ; on peut parfois percevoir des nodules à la surface du foie. Un foie normal est ferme.</div>","frequence":1},{"id":"276-5","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les différents examens biologiques et radiologiques à réaliser en première intention devant une masse abdominale en fonction de l’étiologie suspectée","contenu":"<p>Devant une <span class=\"kw-clinique\">masse abdominale</span>, l’examen complémentaire de référence est la <span class=\"kw-imagerie\">TDM abdomino-pelvienne injectée</span>. Devant une <span class=\"kw-clinique\">hépatomégalie</span>, l’exploration de <span class=\"kw-chiffre\">première intention</span> associe un bilan <span class=\"kw-ttt\">biologique</span> simple et une <span class=\"kw-imagerie\">échographie abdominale</span>.</p>\n      <div class=\"callout callout-info\">📌 L’examen complémentaire de <strong><span class=\"kw-chiffre\">première intention</span> devant une <span class=\"kw-clinique\">masse</span> abdominale</strong> est la <span class=\"kw-imagerie\">TDM abdomino-pelvienne injectée</span>.</div>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Exploration de <span class=\"kw-chiffre\">première intention</span> d’une <span class=\"kw-clinique\">hépatomégalie</span></h4>\n      <table >\n        <thead><tr><th>Volet</th><th>Contenu</th></tr></thead>\n        <tbody>\n          <tr><td>Clinique</td><td>Le foie palpable définit l’<span class=\"kw-clinique\">hépatomégalie</span> en pratique (un foie palpable est le plus souvent pathologique) ; la mesure de la <span class=\"kw-clinique\">flèche hépatique</span> (HMG si <span class=\"kw-chiffre\">&gt; 12 cm</span> sur la ligne médioclaviculaire) n’a plus d’intérêt clinique ; une <span class=\"kw-clinique\">masse</span> de l’hypochondre droit ou de l’ép<span class=\"kw-chiffre\">iga</span>stre mobile avec la respiration est rattachée au foie</td></tr>\n          <tr><td>Biologie</td><td><span class=\"kw-bio\">NFS</span>, <span class=\"kw-bio\">bilan hépatique</span>, <span class=\"kw-bio\">TP</span>, <span class=\"kw-bio\">albumine</span> — à la recherche de signes d’<span class=\"kw-ci\">insuffisance hépatique</span></td></tr>\n          <tr><td><span class=\"kw-imagerie\">Échographie abdominale</span></td><td>Mesure l’<span class=\"kw-clinique\">hépatomégalie</span>, écarte <span class=\"kw-clinique\">les</span> diagnostics différentiels (autres masses abdominales) et oriente l’étiologie</td></tr>\n        </tbody>\n      </table>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Orientation étiologique de l’<span class=\"kw-imagerie\">échographie</span></h4>\n      <table >\n        <thead><tr><th>Signe échographique</th><th>Étiologie évoquée</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-radio\">Foie hyperéchogène</span></td><td><span class=\"kw-etio\">Stéatose</span></td></tr>\n          <tr><td><span class=\"kw-radio\">Contours bosselés, dysmorphie</span> (atrophie du lobe droit, hypertrophie du lobe gauche) avec signes d’<span class=\"kw-clinique\">hypertension</span> portale</td><td><span class=\"kw-etio\">Cirrhose</span></td></tr>\n          <tr><td><span class=\"kw-radio\">Dilatation des veines hépatiques</span></td><td><span class=\"kw-etio\">Insuffisance cardiaque droite</span></td></tr>\n          <tr><td><span class=\"kw-radio\">Dilatation des voies biliaires intra-hépatiques</span></td><td><span class=\"kw-clinique\">Cholestase</span> chronique</td></tr>\n          <tr><td><span class=\"kw-radio\">Nodule hétérogène</span> à plages hyper et hypoéchogènes</td><td><span class=\"kw-etio\">Carcinome hépatocellulaire</span> (<span class=\"kw-clinique\">nodule</span> suspect sur <span class=\"kw-etio\">cirrhose</span>)</td></tr>\n        </tbody>\n      </table>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Exploration de seconde intention selon le contexte</h4>\n      <ul>\n        <li><strong>Absence de <span class=\"kw-clinique\">lésion</span> focale :</strong> <span class=\"kw-bio\">sérologies</span> des <span class=\"kw-bio\">hépatites virales</span>, <span class=\"kw-bio\">hépatite auto-immune</span>, bilan de <span class=\"kw-bio\">surcharge en fer</span> ; <span class=\"kw-imagerie\">élastométrie</span> et test sanguin de fibrose si <span class=\"kw-etio\">stéatose</span> ; <span class=\"kw-imagerie\">cholangio-IRM</span> ou <span class=\"kw-imagerie\">TDM</span> injectée si maladie biliaire suspectée</li>\n        <li><strong><span class=\"kw-clinique\">Lésion</span> focale :</strong> <span class=\"kw-imagerie\">TDM / IRM</span> ; <span class=\"kw-bio\">sérologie des échinococcoses</span> si kyste hépatique ; <span class=\"kw-bio\">hémocultures</span> et <span class=\"kw-bio\">sérologie <em>Entamoeba histolytica</em></span> si <span class=\"kw-clinique\">abcès</span> hépatique</li>\n        <li><strong>Bilan non concluant :</strong> <span class=\"kw-clinique\">ponction-biopsie hépatique</span> si clinique, biologie et imagerie ne permettent pas d’établir la cause</li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 304 — Tumeur du foie · 279 — <span class=\"kw-etio\">Cirrhose</span> · 278 — <span class=\"kw-clinique\">Ictère</span></em></p>","frequence":1},{"id":"276-6","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les indications et contre-indications de la ponction et de la biopsie de foie","contenu":"<p>La <span class=\"kw-def\">ponction-biopsie hépatique (PBH)</span> est indiquée lorsque la clinique, la biologie et l’imagerie ne permettent pas d’établir la cause d’une <span class=\"kw-clinique\">hépatomégalie</span>. Trois voies d’abord sont possibles, choisies selon le <span class=\"kw-def\">terrain</span> et <span class=\"kw-clinique\">les</span> <span class=\"kw-ci\">contre-indications</span>.</p>\n      <div class=\"callout callout-info\">📌 <strong>Indication :</strong> <span class=\"kw-clinique\">démarche diagnostique non concluante</span> — la <span class=\"kw-def\">PBH</span> est indiquée lorsque <span class=\"kw-clinique\">clinique</span>, <span class=\"kw-bio\">biologie</span> et <span class=\"kw-imagerie\">imagerie</span> ne permettent pas d’établir la cause d’une <span class=\"kw-clinique\">hépatomégalie</span>.</div>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Voies de prélèvement</h4>\n      <table >\n        <thead><tr><th>Voie</th><th>Modalités</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\">Percutanée</span></td><td>Voie de <strong><span class=\"kw-chiffre\">première intention</span></strong> ; <span class=\"kw-imagerie\">guidage échographique</span> le plus souvent ; <span class=\"kw-clinique\">anesthésie locale</span></td></tr>\n          <tr><td><span class=\"kw-clinique\">Transjugulaire</span></td><td>Voie <span class=\"kw-imagerie\">transveineuse</span> ; <strong>moins de risque <span class=\"kw-alerte\">hémorragique</span></strong> ; <span class=\"kw-clinique\">anesthésie locale</span> ; <span class=\"kw-ci\">ne permet pas de biopsier une lésion focale</span></td></tr>\n          <tr><td><span class=\"kw-clinique\">Chirurgicale</span></td><td>Réservée à des situations particulières</td></tr>\n        </tbody>\n      </table>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\"><span class=\"kw-ci\">Contre-indications</span></h4>\n      <table >\n        <thead><tr><th>Situation</th><th>Contre-indications</th></tr></thead>\n        <tbody>\n          <tr><td>Voie percutanée (faire alors privilégier la voie transveineuse)</td><td><span class=\"kw-ci\">Ascite, même minime</span> ; <span class=\"kw-ci\">plaquettes &lt; <span class=\"kw-chiffre\">60 G/L</span></span> ; <span class=\"kw-ci\">TP &lt; <span class=\"kw-chiffre\">50 %</span></span> ; <span class=\"kw-ci\">TCA &gt; <span class=\"kw-chiffre\">1,5</span></span> ; hémodialyse ; <span class=\"kw-ttt\">antiagrégants plaquettaires</span>, <span class=\"kw-ttt\">anticoagulants</span>, <span class=\"kw-ttt\">AINS</span></td></tr>\n          <tr><td>Voie transveineuse</td><td><span class=\"kw-ci\">Thrombose des 3 veines sus-hépatiques</span></td></tr>\n          <tr><td>Dans tous <span class=\"kw-clinique\">les</span> cas</td><td><span class=\"kw-ci\">Dilatation des voies biliaires intra-hépatiques</span></td></tr>\n        </tbody>\n      </table>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Où prélever</h4>\n      <ul>\n        <li><strong><span class=\"kw-clinique\">Hépatomégalie diffuse</span> :</strong> la <span class=\"kw-imagerie\">PBH</span> peut être faite <strong>en tout point</strong></li>\n        <li><strong><span class=\"kw-clinique\">Hépatomégalie hétérogène</span> :</strong> prélèvement sur la <span class=\"kw-radio\">lésion focale</span> + <span class=\"kw-chiffre\">1 point</span> du reste du parenchyme (<span class=\"kw-chiffre\">2 prélèvements</span>)</li>\n        <li><strong><span class=\"kw-etio\">Abcès hépatique volumineux</span> :</strong> <span class=\"kw-clinique\">ponction ± drainage</span> sous <span class=\"kw-imagerie\">contrôle échographique</span></li>\n      </ul>\n      <div class=\"callout callout-warn\">⚠️ <strong>Complications de la <span class=\"kw-imagerie\">PBH</span> :</strong> <span class=\"kw-clinique\">douleurs abdominales</span> ; <span class=\"kw-alerte\">effraction pleurale ou biliaire</span> ; <span class=\"kw-alerte\">saignement</span> (<span class=\"kw-alerte\">hématome</span>, <span class=\"kw-alerte\">hémopéritoine</span>, <span class=\"kw-alerte\">choc hémorragique</span>). Elles justifient une <span class=\"kw-clinique\">surveillance FC/PA</span> et un <span class=\"kw-clinique\">alitement</span> pendant <span class=\"kw-chiffre\">≥ 6 h</span>.</div>","frequence":0},{"id":"276-7","rang":"B","rubrique":"Contenu multimédia","titre":"Tomodensitométrie de carcinome hépatocellulaire (CHC) typique chez un patient porteur d’une cirrhose","contenu":"<p>Chez un patient porteur d’une <span class=\"kw-etio\">cirrhose</span>, tout <span class=\"kw-radio\">nodule</span> est suspect : il s’intègre dans le <strong><span class=\"kw-def\">dépistage</span> du <span class=\"kw-clinique\">carcinome</span> hépatocellulaire (CHC)</strong> par <span class=\"kw-imagerie\">échographie</span> semestrielle. Un <span class=\"kw-clinique\">nodule</span> détecté justifie une <span class=\"kw-imagerie\">imagerie en coupe injectée</span> (<span class=\"kw-imagerie\">TDM</span> ou <span class=\"kw-imagerie\">IRM</span>).</p>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Sémiologie <span class=\"kw-imagerie\">TDM</span> du CHC typique</h4>\n      <table >\n        <thead><tr><th>Temps d’acquisition</th><th>Aspect du <span class=\"kw-clinique\">nodule</span></th></tr></thead>\n        <tbody>\n          <tr><td>Sans injection</td><td><span class=\"kw-clinique\">Nodule</span> <span class=\"kw-radio\">iso ou hypodense</span></td></tr>\n          <tr><td><span class=\"kw-imagerie\">Temps artériel</span></td><td><span class=\"kw-radio\">Hyperdensité</span> du <span class=\"kw-clinique\">nodule</span> — <span class=\"kw-imagerie\">wash-in</span> (rehaussement intense)</td></tr>\n          <tr><td><span class=\"kw-imagerie\">Temps portal</span></td><td>Lavage du contraste, aspect <span class=\"kw-radio\">hypovasculaire</span> — <span class=\"kw-imagerie\">wash-out</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Mécanisme.</strong> Le CHC est vascularisé <span class=\"kw-alerte\">exclusivement par l’artère hépatique</span>, à la différence du parenchyme hépatique non <span class=\"kw-etio\">tumoral</span>, lui aussi vascularisé par la <span class=\"kw-clinique\">veine porte</span>. C’est pourquoi le foie normal apparaît gris au <span class=\"kw-imagerie\">temps artériel</span> et devient blanc au <span class=\"kw-imagerie\">temps portal</span>, tandis que le CHC se rehausse précocement puis se lave.</p>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/276/tdm-chc-cirrhose.png\" alt=\"TDM abdomino-pelvienne, 4 coupes axiales aux temps sans injection, artériel, portal et tardif, montrant un nodule de carcinome hépatocellulaire spontanément hypodense, hyper-rehaussé au temps artériel puis présentant un lavage aux temps portal et tardif\" loading=\"lazy\">\n        <figcaption><span class=\"kw-imagerie\">TDM abdomino-pelvienne</span>, coupes axiales (4 temps). <span class=\"kw-clinique\">Lésion</span> <span class=\"kw-radio\">hypodense spontanément</span> (1), <span class=\"kw-radio\">hyper-rehaussée au temps artériel</span> (2 — prise de contraste supérieure au parenchyme hépatique), présentant un <span class=\"kw-radio\">lavage aux temps portal et tardif</span> (3 — devenant hypodense par rapport au parenchyme) : aspect typique de <span class=\"kw-etio\">carcinome hépatocellulaire</span>. Source : banque imagerie « Imagerie à connaître » (item 276).</figcaption>\n      </figure>\n      <div class=\"callout callout-info\">📌 Un <span class=\"kw-clinique\">nodule</span> de <span class=\"kw-chiffre\">&gt; 1 cm</span> présentant <span class=\"kw-imagerie\">wash-in</span> et <span class=\"kw-imagerie\">wash-out</span>, développé sur une <span class=\"kw-etio\">cirrhose certaine</span> et validé en <strong><span class=\"kw-def\">RCP</span></strong>, permet un diagnostic non invasif de CHC, sans <span class=\"kw-bio\">biopsie</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 304 — Tumeur du foie · 279 — <span class=\"kw-etio\">Cirrhose</span></em></p>","frequence":0,"liens":[{"href":"https://radiopaedia.org/articles/liver","label":"Radiopaedia : Liver"},{"href":"https://radiopaedia.org/cases/liver-segments-annotated-ct-1","label":"Radiopaedia : Liver segments annotated ct 1"},{"href":"http://radiopaedia.org","label":"radiopaedia.org"}]},{"id":"276-8","rang":"B","rubrique":"Contenu multimédia","titre":"Tomodensitométrie de métastases hépatiques","contenu":"<p>Devant une <span class=\"kw-radio\">tumeur hépatique solide</span> sans maladie chronique du foie documentée, l’analyse repose sur la <span class=\"kw-imagerie\">cinétique de prise du produit de contraste</span> en <span class=\"kw-imagerie\">échographie</span> de contraste, <span class=\"kw-imagerie\">TDM</span> ou <span class=\"kw-imagerie\">IRM</span>, et sur la recherche d’un <span class=\"kw-alerte\">contexte de cancer extra-hépatique</span> (sexe, âge, cancer connu).</p>\n      <p>Le <span class=\"kw-alerte\">contexte d’un cancer extra-hépatique connu</span> pèse fortement en faveur du diagnostic de métastase. La <span class=\"kw-imagerie\">TEP-FDG</span> (ou <span class=\"kw-imagerie\">TEP</span>-choline), en cas de <span class=\"kw-clinique\">lésion</span> hépatique isolée, aide au <span class=\"kw-def\">diagnostic différentiel</span> entre <span class=\"kw-etio\">métastase</span>, <span class=\"kw-etio\">cholangiocarcinome</span> et tumeur bénigne.</p>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Sémiologie <span class=\"kw-imagerie\">TDM</span> des métastases hépatiques</h4>\n      <table >\n        <thead><tr><th>Temps d’acquisition</th><th>Aspect du <span class=\"kw-clinique\">nodule</span></th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-imagerie\">Temps artériel</span></td><td><span class=\"kw-radio\">Absence de rehaussement</span> de la <span class=\"kw-clinique\">lésion</span></td></tr>\n          <tr><td><span class=\"kw-imagerie\">Temps portal</span></td><td><span class=\"kw-radio\">Absence de rehaussement</span> de la <span class=\"kw-clinique\">lésion</span></td></tr>\n        </tbody>\n      </table>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/276/tdm-metastases-hepatiques.png\" alt=\"TDM abdomino-pelvienne, coupes axiales avec injection : à gauche métastases hépatiques classiques discrètement rehaussées au temps portal en périphérie mais restant hypodenses ; à droite métastases hyper-rehaussées au temps artériel plus que le parenchyme hépatique\" loading=\"lazy\">\n        <figcaption><span class=\"kw-imagerie\">TDM abdomino-pelvienne</span>, coupes axiales. <strong>Métastases « classiques »</strong> (temps portal, 2 patients distincts) : lésions <span class=\"kw-radio\">discrètement rehaussées de façon hétérogène, plutôt en périphérie, mais restant hypodenses</span> par rapport au parenchyme. <strong>Métastases hyper-rehaussées</strong> (temps artériel) : <span class=\"kw-radio\">lésions rehaussées plus que le parenchyme hépatique</span> — cas particuliers du <span class=\"kw-etio\">cancer du rein, de la thyroïde, mélanome, tumeur neuro-endocrine</span>. Source : banque imagerie « Imagerie à connaître » (item 276).</figcaption>\n      </figure>\n      <div class=\"callout callout-info\">📌 Une <span class=\"kw-clinique\">lésion</span> hépatique <span class=\"kw-radio\">sans rehaussement aux temps artériel et portal</span> oriente vers une <span class=\"kw-etio\">métastase</span> ou un adénome hépatocellulaire ; le <span class=\"kw-alerte\">contexte oncologique</span> (cancer extra-hépatique connu) tranche.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 304 — Tumeur du foie · 279 — <span class=\"kw-etio\">Cirrhose</span></em></p>","frequence":0},{"id":"276-9","rang":"B","rubrique":"Contenu multimédia","titre":"Tomodensitométrie de kyste hépatique typique","contenu":"<p>Devant une <span class=\"kw-radio\">lésion hépatique kystique</span> sans maladie chronique du foie, l’<span class=\"kw-imagerie\">échographie</span> détermine si la <span class=\"kw-clinique\">lésion</span> est un <strong>kyste biliaire simple</strong>. <span class=\"kw-clinique\">Les</span> principales tumeurs kystiques à connaître sont : le kyste biliaire simple, les kystes parasitaires (<span class=\"kw-etio\">hydatidose</span>, échinococcose alvéolaire), les <span class=\"kw-clinique\">abcès</span> amibiens, les <span class=\"kw-clinique\">abcès</span> à pyogènes et les tumeurs nécrosées.</p>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Critères échographiques du kyste biliaire simple</h4>\n      <ul>\n        <li><span class=\"kw-clinique\">Lésion</span> <span class=\"kw-radio\">parfaitement liquidienne</span> (anéchogène, avec renforcement postérieur)</li>\n        <li><span class=\"kw-radio\">Absence de toute paroi ou cloison interne</span></li>\n      </ul>\n      <p>Si l’<span class=\"kw-imagerie\">échographie</span> confirme ces critères, le diagnostic de <span class=\"kw-etio\">kyste biliaire simple</span> est établi. On réalise néanmoins des <span class=\"kw-bio\">tests sérologiques d’hydatidose</span> chez <span class=\"kw-clinique\">les</span> sujets ayant vécu en zone d’endémie au <span class=\"kw-def\">contact</span> de chiens.</p>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Sémiologie <span class=\"kw-imagerie\">TDM</span> du kyste biliaire simple typique</h4>\n      <table >\n        <thead><tr><th>Critère</th><th>Aspect typique</th></tr></thead>\n        <tbody>\n          <tr><td>Forme</td><td><span class=\"kw-clinique\">Lésion</span> <span class=\"kw-radio\">arrondie, à contours nets</span></td></tr>\n          <tr><td>Densité spontanée</td><td><span class=\"kw-radio\">Densité hydrique</span> homogène</td></tr>\n          <tr><td>Paroi</td><td><span class=\"kw-radio\">Paroi fine, voire invisible</span> ; pas de cloison interne</td></tr>\n          <tr><td>Après injection</td><td><span class=\"kw-radio\">Aucun rehaussement</span> (ni de la <span class=\"kw-clinique\">lésion</span>, ni d’une paroi)</td></tr>\n        </tbody>\n      </table>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/276/tdm-kyste-hepatique.png\" alt=\"TDM abdomino-pelvienne, coupes axiales sans injection puis avec injection au temps portal, montrant à la pointe du foie droit une formation bien limitée à bords nets, sphérique, homogène, hypodense de densité liquidienne, sans cloison ni paroi et sans rehaussement\" loading=\"lazy\">\n        <figcaption><span class=\"kw-imagerie\">TDM abdomino-pelvienne</span>, coupes axiales (sans injection puis temps portal). <span class=\"kw-radio\">Formation bien limitée, à bords nets, sphérique ou ovale, homogène</span>, <span class=\"kw-radio\">hypodense de densité liquidienne, sans cloison ni paroi, sans rehaussement</span> après injection (pointe du foie droit, flèches grises) : aspect typique de <span class=\"kw-etio\">kyste hépatique simple</span>. Source : banque imagerie « Imagerie à connaître » (item 276).</figcaption>\n      </figure>\n      <p>Si l’<span class=\"kw-imagerie\">échographie</span> ne répond pas aux critères du kyste simple, la <span class=\"kw-clinique\">lésion</span> est précisée par <span class=\"kw-imagerie\">TDM, IRM ou échographie de contraste</span> : il peut alors s’agir d’une tumeur bénigne à potentiel malin, d’une <span class=\"kw-etio\">tumeur maligne</span>, d’un <span class=\"kw-etio\">kyste hydatique</span> ou d’un kyste biliaire simple modifié par une hémorragie intrakystique.</p>\n      <div class=\"callout callout-info\">📌 Le <span class=\"kw-etio\">kyste biliaire simple</span> est un diagnostic d’imagerie : <span class=\"kw-clinique\">lésion</span> <span class=\"kw-radio\">parfaitement liquidienne</span>, <span class=\"kw-radio\">sans paroi ni cloison</span>, <span class=\"kw-radio\">sans rehaussement</span>. Toute paroi épaisse, cloison interne, composante tissulaire ou rehaussement doit remettre en cause le diagnostic et faire évoquer un <span class=\"kw-etio\">kyste hydatique</span>, une <span class=\"kw-etio\">tumeur kystique</span> (bénigne à potentiel malin ou maligne) ou un <span class=\"kw-clinique\">abcès</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 304 — Tumeur du foie · 279 — <span class=\"kw-etio\">Cirrhose</span></em></p>","frequence":0}],"astuces":[],"strategie":{"principes":"<p><em>Stratégie de prise en charge à compléter — non disponible dans la source GitHub pour cet item.</em></p>"},"liensGlobaux":[{"href":"https://www.fmcgastro.org/postu-main/archives/postu-2012-paris/textes-postu-2012-paris/diagnostic-des-nodules-sur-cirrhose-quelle-est-la-place-de-la-biopsie%E2%80%88/","label":"Diagnostic des nodules sur cirrhose. Quelle est la place de la biopsie ? – FMC-HGE"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Hépatomégalie confirmée — Foie palpable (> 12 cm en ligne médioclaviculaire). Échographie en 1re intention : diffuse/sectorielle, homogène ou hétérogène","detail":"<h4>CAT — <span class=\"kw-clinique\">hépatomégalie</span> : démarche diagnostique — Caractérisation échographique → orientation étiologique</h4>","branches":[{"to":"q-homogene","label":"Échostructure homogène (diffuse ou sectorielle)","color":"blue"},{"to":"q-mcf","label":"Échostructure hétérogène (nodules / plages anormales)","color":"amber"}]},{"id":"q-homogene","kind":"decision","label":"Hépatomégalie homogène : orientation étiologique ? — Clinique + biologie + échographie ± doppler","branches":[{"to":"t-steatose","label":"Foie hyperéchogène · alcool ou syndrome métabolique","color":"amber"},{"to":"t-cirrhose","label":"Contours bosselés · dysmorphie · foie dur à bord tranchant","color":"amber"},{"to":"t-cardiaque","label":"Veines hépatiques et VCI dilatées · insuffisance cardiaque droite","color":"amber"}]},{"id":"t-steatose","kind":"terminal","label":"Stéatose / stéatohépatite","color":"amber","detail":"<h4>Contexte</h4><ul><li><span class=\"kw-etio\">Consommation excessive d’alcool</span> ou <span class=\"kw-etio\">syndrome métabolique</span></li><li>Tour de taille <span class=\"kw-chiffre\">&gt; 102 cm</span> (homme) / <span class=\"kw-chiffre\">&gt; 88 cm</span> (femme)</li></ul><h4><span class=\"kw-imagerie\">Échographie</span></h4><ul><li><span class=\"kw-radio\">Foie hyperéchogène</span> (« foie brillant »)</li></ul><h4>Biologie</h4><ul><li>Élévation modérée des <span class=\"kw-bio\">transaminases</span> et de la <span class=\"kw-bio\">γ-GT</span></li></ul><h4><span class=\"kw-chiffre\">2e intention</span></h4><ul><li>Évaluation de la <span class=\"kw-bio\">fibrose hépatique</span> : <span class=\"kw-imagerie\">élastométrie</span> et/ou test sanguin de fibrose</li></ul>"},{"id":"t-cirrhose","kind":"terminal","label":"Cirrhose","color":"amber","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Foie dur</span> à <span class=\"kw-clinique\">bord inférieur tranchant</span>, surface parfois nodulaire</li><li>Signes d’<span class=\"kw-clinique\">insuffisance hépatocellulaire</span> : <span class=\"kw-clinique\">ictère</span>, angiomes stellaires, érythrose palmaire, ongles blancs, encéphalopathie</li><li>Signes d’<span class=\"kw-clinique\">hypertension portale</span> : <span class=\"kw-clinique\">ascite</span>, circulation veineuse collatérale, <span class=\"kw-clinique\">splénomégalie</span></li></ul><h4><span class=\"kw-imagerie\">Échographie</span></h4><ul><li><span class=\"kw-radio\">Contours irréguliers / bosselés</span>, <span class=\"kw-radio\">dysmorphie</span> (atrophie du lobe droit, hypertrophie du lobe gauche)</li><li>Signes d’<span class=\"kw-clinique\">HTP</span> : <span class=\"kw-radio\">splénomégalie</span>, voies de dérivation, flux porte inversé au doppler</li></ul><h4>Biologie</h4><ul><li><span class=\"kw-bio\">↓ TP</span>, <span class=\"kw-bio\">↓ facteur V</span>, <span class=\"kw-bio\">↑ INR</span>, <span class=\"kw-bio\">↓ albumine</span>, <span class=\"kw-bio\">↑ bilirubine</span> ; thrombopénie (hypersplénisme)</li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li><span class=\"kw-def\">Dépistage</span> du <span class=\"kw-etio\">CHC</span> : <span class=\"kw-imagerie\">échographie</span> + <span class=\"kw-bio\">AFP</span> tous <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">6 mois</span></li></ul><h4>Renvoi</h4><ul><li>Item 279 — Cirrhose</li></ul>"},{"id":"t-cardiaque","kind":"terminal","label":"Foie cardiaque","color":"amber","detail":"<h4>Contexte</h4><ul><li><span class=\"kw-etio\">Insuffisance cardiaque droite</span>, <span class=\"kw-etio\">péricardite constrictive</span> (exceptionnel : <span class=\"kw-etio\">syndrome de Budd-Chiari</span>)</li></ul><h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Reflux hépatojugulaire</span>, expansion systolique du foie, signes d’<span class=\"kw-ci\">insuffisance cardiaque</span> droite</li></ul><h4><span class=\"kw-imagerie\">Échographie</span></h4><ul><li><span class=\"kw-radio\">Dilatation des veines hépatiques</span> et de la <span class=\"kw-radio\">VCI</span></li></ul><h4>CAT</h4><ul><li><span class=\"kw-imagerie\">Échographie cardiaque (ETT)</span> devant une dilatation des veines hépatiques + VCI</li></ul>"},{"id":"q-mcf","kind":"decision","label":"Existe-t-il une maladie chronique du foie documentée ? — ATCD, facteurs de risque, clinique, biologie, échographie (± biopsie en foie non tumoral)","branches":[{"to":"q-mcf-type","label":"Oui — maladie chronique du foie (cirrhose +++)","color":"red"},{"to":"q-nature","label":"Non — pas de maladie chronique du foie","color":"blue"}]},{"id":"q-mcf-type","kind":"decision","label":"Quel diagnostic écarter en priorité ? — Toute image nodulaire sur cirrhose = CHC jusqu’à preuve du contraire","branches":[{"to":"t-chc","label":"Nodule > 1 cm · wash-in artériel + wash-out portal/tardif","color":"red"},{"to":"t-cholangio","label":"Dilatation des voies biliaires intra-hépatiques","color":"red"}]},{"id":"t-chc","kind":"terminal","label":"Carcinome hépatocellulaire (CHC)","color":"red","detail":"<h4><span class=\"kw-def\">Terrain</span></h4><ul><li>Survient sur <span class=\"kw-etio\">cirrhose</span> (<span class=\"kw-def\">incidence</span> <span class=\"kw-chiffre\">1 à 5 %/an</span>) — diagnostic le plus fréquent d’une <span class=\"kw-clinique\">lésion</span> hétérogène sur foie chronique</li></ul><h4>Imagerie</h4><ul><li><span class=\"kw-radio\">Nodule hétérogène</span> &gt; <span class=\"kw-chiffre\">1 cm</span>, plages hyper- et hypoéchogènes à l’<span class=\"kw-imagerie\">échographie</span></li><li><span class=\"kw-imagerie\">TDM/IRM injectées</span> : <span class=\"kw-radio\">wash-in</span> (hyperdensité artérielle) puis <span class=\"kw-radio\">wash-out</span> (lavage au temps portal/tardif)</li></ul><h4>Biologie</h4><ul><li><span class=\"kw-bio\">AFP</span> &gt; <span class=\"kw-chiffre\">400 ng/mL</span> : valeur diagnostique chez le cirrhotique (mais non suffisante)</li></ul><h4><span class=\"kw-ttt\">Biopsie</span></h4><ul><li><span class=\"kw-ttt\">Biopsie</span> écho-guidée + biopsie en foie normal si l’imagerie n’est pas caractéristique ; non indispensable si <span class=\"kw-clinique\">nodule</span> &gt;<span class=\"kw-chiffre\"> 1 cm</span> avec wash-in/wash-out sur cirrhose certaine validé en <span class=\"kw-ttt\">RCP</span></li></ul><h4>Renvoi</h4><ul><li>Item 304 — Tumeur du foie · Item 279 — Cirrhose</li></ul>"},{"id":"t-cholangio","kind":"terminal","label":"Cholangiocarcinome","color":"red","detail":"<h4>Orientation</h4><ul><li>Plus rare que le CHC ; suspecté devant une <span class=\"kw-radio\">dilatation des voies biliaires intra-hépatiques</span></li></ul><h4>Imagerie</h4><ul><li><span class=\"kw-imagerie\">Cholangio-IRM</span> pour préciser l’obstacle biliaire ; <span class=\"kw-imagerie\">TDM/IRM triphasiques</span></li></ul><h4>Renvoi</h4><ul><li>Item 304 — Tumeur du foie</li></ul>"},{"id":"q-nature","kind":"decision","label":"Lésion kystique ou solide à l’échographie ? — L’échographie tranche entre contenu liquidien et tissulaire","branches":[{"to":"q-kystique","label":"Lésion kystique (liquidienne)","color":"blue"},{"to":"t-solide","label":"Lésion solide (même partiellement liquidienne)","color":"amber"}]},{"id":"q-kystique","kind":"decision","label":"Caractéristiques de la lésion kystique ? — Rechercher paroi, cloison, contexte septique, exposition parasitaire","branches":[{"to":"t-kyste-simple","label":"Parfaitement liquidienne, sans paroi ni cloison","color":"green"},{"to":"t-hydatique","label":"Paroi / cloison · séjour en zone d’endémie","color":"amber"},{"to":"t-abces","label":"Contexte septique fébrile · paroi épaisse","color":"red"}]},{"id":"t-kyste-simple","kind":"terminal","label":"Kyste biliaire simple","color":"green","detail":"<h4><span class=\"kw-imagerie\">Échographie</span></h4><ul><li><span class=\"kw-radio\">Lésion parfaitement liquidienne</span>, <span class=\"kw-radio\">anéchogène</span>, <span class=\"kw-radio\">sans paroi ni cloison</span>, <span class=\"kw-radio\">sans rehaussement</span></li></ul><h4>CAT</h4><ul><li>Diagnostic d’imagerie ; réaliser une <span class=\"kw-bio\">sérologie hydatidose</span> chez <span class=\"kw-clinique\">les</span> sujets ayant vécu en zone d’endémie</li></ul><h4>Alerte</h4><ul><li>Toute <span class=\"kw-alerte\">paroi épaisse</span>, <span class=\"kw-alerte\">cloison</span> ou <span class=\"kw-alerte\">composante tissulaire</span> remet en cause le diagnostic</li></ul>"},{"id":"t-hydatique","kind":"terminal","label":"Kyste hydatique","color":"amber","detail":"<h4>Contexte</h4><ul><li><span class=\"kw-etio\">Séjour en zone d’endémie</span>, <span class=\"kw-def\">contact</span> avec des chiens (<span class=\"kw-etio\">hydatidose</span> / échinococcose)</li></ul><h4>Imagerie</h4><ul><li><span class=\"kw-radio\">Kyste à paroi propre, cloisons internes / vésicules filles</span> ; précision par <span class=\"kw-imagerie\">TDM ou IRM</span></li></ul><h4>Biologie</h4><ul><li><span class=\"kw-bio\">Sérologie des échinococcoses</span></li></ul>"},{"id":"t-abces","kind":"terminal","label":"Abcès hépatique","color":"red","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-alerte\">Syndrome septique</span> (<span class=\"kw-clinique\">fièvre</span>, frissons) ; <span class=\"kw-clinique\">abcès</span> <span class=\"kw-etio\">amibien</span> ou <span class=\"kw-etio\">bactérien</span></li></ul><h4>Imagerie</h4><ul><li><span class=\"kw-radio\">Réhaussement périphérique au temps artériel, centre non réhaussé</span> (= <span class=\"kw-clinique\">abcès</span> ou tumeur nécrosée)</li></ul><h4>Biologie</h4><ul><li><span class=\"kw-bio\">Hémocultures</span>, <span class=\"kw-bio\">sérologie Entamoeba histolytica</span></li></ul><h4>CAT</h4><ul><li>Si <span class=\"kw-clinique\">abcès</span> volumineux : <span class=\"kw-ttt\">ponction ± drainage sous contrôle échographique</span></li></ul>"},{"id":"t-solide","kind":"terminal","label":"Tumeur solide : métastase / hémangiome","color":"amber","detail":"<h4>Démarche</h4><ul><li>Chercher un <span class=\"kw-etio\">contexte de cancer extra-hépatique</span> ; préciser la <span class=\"kw-radio\">cinétique de prise de contraste</span> (<span class=\"kw-imagerie\">échographie</span> de contraste, <span class=\"kw-imagerie\">TDM</span> ou <span class=\"kw-imagerie\">IRM</span> triphasiques)</li></ul><h4>Hémangiome (bénin)</h4><ul><li><span class=\"kw-radio\">Réhaussement en mottes périphériques, progressif de la périphérie vers le centre</span> ; très hyperintense et homogène en <span class=\"kw-imagerie\">IRM T2</span></li></ul><h4>Métastase / adénome</h4><ul><li><span class=\"kw-radio\">Absence de réhaussement aux temps artériel et portal</span> ; la notion de <span class=\"kw-etio\">cancer extra-hépatique</span> pèse fortement</li></ul><h4>Piège</h4><ul><li>Un <span class=\"kw-radio\">réhaussement net au temps artériel avec wash-out</span> doit faire évoquer un <span class=\"kw-etio\">CHC</span> ; une <span class=\"kw-ttt\">ponction-biopsie</span> peut être indiquée</li></ul>"}]},"cards":[{"i":"04388e6f8602","n":276,"o":"276-1","u":"Définition","t":"Connaître la définition d’une masse abdominale","q":"Quelle est la définition d'une masse abdominale ?","a":"<p>Une masse abdominale se définit comme une <strong>augmentation de volume</strong> d’un organe ou d’une région de l’abdomen.</p>"},{"i":"7f0cf3535529","n":276,"o":"276-1","u":"Définition","t":"Connaître la définition d’une masse abdominale","q":"Quelles sont les premières entités à éliminer devant la découverte d'une masse abdominale lors de l'examen clinique ?","a":"<p>Il convient d'éliminer en premier lieu les <ul><li><strong>éventrations</strong></li><li>les <strong>hernies</strong></li><li>les <strong>distensions abdominales</strong></li></ul></p>"},{"i":"eafa09af18ca","n":276,"o":"276-1","u":"Définition","t":"Connaître la définition d’une masse abdominale","q":"Quels sont les différents caractères à analyser lors de l'examen clinique d'une masse abdominale ?","a":"<p>L'examen clinique d'une masse abdominale doit préciser :</p><ul><li>sa <strong>localisation</strong> sur un quadrant</li><li>sa <strong>taille</strong>, sa <strong>forme</strong>, ses <strong>contours</strong></li><li>sa <strong>consistance</strong></li><li>son caractère <strong>mobile ou fixe</strong></li><li>son caractère <strong>indolore ou douloureux</strong></li><li>les findings à la <strong>percussion</strong> et à l'<strong>auscultation</strong></li></ul>"},{"i":"6639130bb39a","n":276,"o":"276-4","u":"Diagnostic positif","t":"Connaître les éléments de l’interrogatoire et de l’examen physique aidant au diagnostic d’hépatomégalie et de masse abdominale","q":"Comment caractériser une masse abdominale à l'examen physique ?","a":"<p>La caractérisation d'une masse abdominale à l'examen physique comprend :</p><ul><li>Sa <strong>localisation</strong> par rapport aux quadrants abdominaux.</li><li>Sa <strong>taille et sa forme</strong> (arrondie, polylobée).</li><li>Ses <strong>contours</strong> (réguliers, irréguliers, nets, mal définis).</li><li>Sa <strong>consistance</strong> (rénitente, ferme, dure, homogène, non homogène).</li><li>Sa <strong>mobilité</strong> (mobile, fixe, mobilité avec la respiration - en faveur d'une origine hépatique).</li><li>Sa <strong>sensibilité</strong> (indolore, douloureuse, spontanément ou à la palpation).</li><li>La <strong>percussion</strong> (sonorité ou matité).</li><li>L'<strong>auscultation</strong> (recherche d'un souffle).</li></ul>"},{"i":"bcbbd1914a71","n":276,"o":"276-4","u":"Diagnostic positif","t":"Connaître les éléments de l’interrogatoire et de l’examen physique aidant au diagnostic d’hépatomégalie et de masse abdominale","q":"Quels sont les éléments clés à rechercher lors de l'interrogatoire devant une hépatomégalie ou une masse abdominale pour orienter le diagnostic ?","a":"<p>Lors de l'interrogatoire, il faut rechercher :</p><ul><li>Les <strong>circonstances de découverte</strong> (fortuite, douleur, ictère, dépistage).</li><li>La <strong>date d'apparition et l'évolution</strong> de la masse.</li><li>Le <strong>contexte</strong> (voyage en zone d'endémie, facteurs de risque de cirrhose ou d'hépatite virale).</li><li>Les <strong>antécédents</strong> (médicaux, chirurgicaux, gynécologiques, familiaux de cancers).</li><li>Les <strong>traitements en cours</strong> (notamment les anticoagulants).</li><li>Les <strong>signes associés</strong> (fièvre, sueurs, amaigrissement, troubles du transit, signes urinaires ou gynécologiques).</li><li>La <strong>date des dernières règles</strong> chez la femme non ménopausée pour évoquer une éventuelle grossesse extra-utérine.</li></ul>"},{"i":"cc2523cc76a6","n":276,"o":"276-4","u":"Diagnostic positif","t":"Connaître les éléments de l’interrogatoire et de l’examen physique aidant au diagnostic d’hépatomégalie et de masse abdominale","q":"Quels sont les signes cliniques orientant vers une hépatopathie spécifiques à rechercher à l'examen physique en cas d'hépatomégalie ?","a":"<p>À l'examen physique, il faut rechercher les signes suivants :</p><ul><li>Signes de <strong>syndrome septique</strong> (fièvre, frissons).</li><li>Signes de <strong>cholestase</strong> (ictère, prurit, selles décolorées, urines foncées).</li><li>Signes d'<strong>insuffisance hépatocellulaire</strong> (ictère conjonctival ou cutané, fœtor hepaticus, angiomes stellaires, érythrose palmaire, ongles blancs, encéphalopathie hépatique avec astérixis, inversion du cycle nycthéméral, hypogonadisme).</li><li>Signes d'<strong>hypertension portale</strong> (ascite, circulation veineuse collatérale abdominale, splénomégalie). La palpation d'un <strong>foie dur à bord inférieur tranchant</strong> est très évocatrice d'une cirrhose.</li><li>Signes de <strong>métastases</strong> (palpation du foie, aires ganglionnaires comme l'adénopathie de Troisier, nodules de carcinose, touchers pelviens).</li><li>Signes d'<strong>insuffisance cardiaque droite</strong> (reflux hépatojugulaire, expansion systolique du foie, ascite).</li></ul>"}]};